changeSet.sql:
create table organizations ( id bigint generated always as identity primary key, user_id bigint not null, name varchar(255) not null, handle varchar(255) not null, logo varchar(255), -- NULL = wszystkie sekcje widoczne (mirror Organization::enabled_sections -- w Laravelu); pusta tablica = żadna widoczna (stan startowy nowej organizacji). enabled_sections text[], created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
constraint organizations_handle_unique unique (handle) );
create index organizations_user_id_idx on organizations (user_id);
